# One-click: open all 32 VelaGuard Modbus Slave windows (named by sensor).
#
# Usage (PowerShell):
#   .\scripts\open_velaguard_mbslaves.ps1
#   .\scripts\open_velaguard_mbslaves.ps1 -OpenConnection -KeepOpenSeconds 3600
#   .\scripts\open_velaguard_mbslaves.ps1 -Dir "$env:USERPROFILE\Documents\mthings"
#
# Expects files: NN_<sensor>.mbs  (e.g. 01_温湿度-导轨V1.5.mbs)
# Fallback: also accepts legacy velaguard_slaveNN.mbs

param(
  [string]$Dir = "$env:USERPROFILE\Documents\mthings",
  [int]$ComPort = 6,
  [int]$Baud = 9600,
  [switch]$OpenConnection,
  [switch]$KeepOpen,
  [int]$KeepOpenSeconds = 0
)

$ErrorActionPreference = "Stop"

function Get-SafeSensorName([string]$Name) {
  $n = $Name -replace '^\[S\]', ''
  $n = $n.Trim()
  foreach ($c in @('<', '>', ':', '"', '/', '\', '|', '?', '*')) {
    $n = $n.Replace($c, '_')
  }
  $n = $n -replace '\s+', ''
  if ([string]::IsNullOrWhiteSpace($n)) { $n = 'sensor' }
  return $n
}

function Resolve-SlaveMbs([string]$Root, [int]$Addr, [string]$Name) {
  $safe = Get-SafeSensorName $Name
  $named = Join-Path $Root ("{0:D2}_{1}.mbs" -f $Addr, $safe)
  if (Test-Path $named) { return $named }
  $legacy = Join-Path $Root ("velaguard_slave{0:D2}.mbs" -f $Addr)
  if (Test-Path $legacy) { return $legacy }
  return $null
}

if (-not (Test-Path $Dir)) {
  throw "Directory not found: $Dir"
}

$repoRoot = Split-Path -Parent $PSScriptRoot
$csvPath = Join-Path $repoRoot "config\modbus-slave\velaguard_slaves.csv"

$files = @()
if (Test-Path $csvPath) {
  $slaves = Import-Csv $csvPath
  foreach ($s in $slaves) {
    $addr = [int]$s.addr
    $path = Resolve-SlaveMbs $Dir $addr $s.name
    if (-not $path) {
      throw "Missing mbs for addr=$addr name=$($s.name) under $Dir"
    }
    $files += [pscustomobject]@{ Addr = $addr; Name = $s.name; File = $path }
  }
}
else {
  # No CSV: open every NN_*.mbs (and legacy) by numeric prefix.
  $named = Get-ChildItem -Path $Dir -Filter "*.mbs" |
    Where-Object { $_.Name -match '^\d{2}_.+\.mbs$' } |
    Sort-Object Name
  if ($named.Count -eq 0) {
    $named = 1..32 | ForEach-Object {
      Get-Item (Join-Path $Dir ("velaguard_slave{0:D2}.mbs" -f $_)) -ErrorAction SilentlyContinue
    } | Where-Object { $_ }
  }
  if ($named.Count -eq 0) {
    throw "No NN_<sensor>.mbs (or velaguard_slaveNN.mbs) in $Dir"
  }
  foreach ($f in $named) {
    $addr = [int]($f.BaseName.Substring(0, 2))
    $files += [pscustomobject]@{ Addr = $addr; Name = $f.BaseName; File = $f.FullName }
  }
}

Write-Output "=== Open $($files.Count) Modbus Slave docs from $Dir ==="

try {
  $app = New-Object -ComObject Mbslave.Application
}
catch {
  throw "Mbslave.Application COM failed. Install Modbus Slave and run it once."
}

$app.Connection = 0
$app.SerialPort = $ComPort
$app.BaudRate = $Baud
$app.DataBits = 8
$app.Parity = 0
$app.StopBits = 1
try { $app.Mode = 0 } catch {}

$docs = @()
foreach ($f in ($files | Sort-Object Addr)) {
  $doc = New-Object -ComObject Mbslave.Document
  $opened = $false
  try {
    $opened = [bool]$doc.Open($f.File)
  }
  catch {
    # Some builds expose Open via late-bound call only.
    try {
      $opened = [bool]$doc.Open([string]$f.File)
    }
    catch {
      Write-Warning "COM Open failed for $($f.File): $($_.Exception.Message)"
    }
  }

  if (-not $opened) {
    # Fallback: shell-associate open (may spawn separate processes).
    Start-Process -FilePath $f.File | Out-Null
    Write-Output ("addr={0,2} shell-open {1}" -f $f.Addr, (Split-Path $f.File -Leaf))
    continue
  }

  try { $doc.ShowWindow() | Out-Null } catch {}
  $docs += $doc
  Write-Output ("addr={0,2} opened {1}" -f $f.Addr, (Split-Path $f.File -Leaf))
}

if ($OpenConnection) {
  $st = $app.OpenConnection()
  Write-Output "OpenConnection status=$st"
}

$holdSec = $KeepOpenSeconds
if ($KeepOpen -and $holdSec -le 0) { $holdSec = 7200 }

if ($holdSec -gt 0) {
  Write-Output "Holding $($docs.Count) COM docs for ${holdSec}s (Ctrl+C to stop)..."
  try {
    Start-Sleep -Seconds $holdSec
  }
  finally {
    try { $app.CloseConnection() | Out-Null } catch {}
  }
}
else {
  Write-Output ""
  Write-Output "Windows stay open. Tip: -OpenConnection -KeepOpenSeconds 3600 after releasing COM$ComPort."
}

