# One-click: open all 32 VelaGuard Modbus Slave windows (named by sensor).
#
# By default opens via shell association so windows STAY OPEN after this script exits.
# COM mode (-ComHold) keeps Document objects alive until you press Enter / timeout.
#
# Usage:
#   .\scripts\open_velaguard_mbslaves.ps1
#   .\scripts\open_velaguard_mbslaves.ps1 -OpenConnection -ComHold
#   .\scripts\open_velaguard_mbslaves.ps1 -Dir "$env:USERPROFILE\Documents\mthings"
#
# Expects: NN_<sensor>.mbs  (e.g. 01_温湿度-导轨V1.5.mbs)
# Fallback: velaguard_slaveNN.mbs

param(
  [string]$Dir = "$env:USERPROFILE\Documents\mthings",
  [int]$ComPort = 6,
  [int]$Baud = 9600,
  [switch]$OpenConnection,
  # Keep COM Document refs alive (needed for -OpenConnection). Default shell-open
  # does not need this — windows outlive the script.
  [switch]$ComHold,
  [switch]$KeepOpen,
  [int]$KeepOpenSeconds = 0
)

$ErrorActionPreference = "Stop"

function Get-SafeSensorName([string]$Name) {
  $n = $Name -replace '^\[S\]', ''
  $n = $n.Trim()
  foreach ($c in @('<', '>', ':', '"', '/', '\', '|', '?', '*')) {
    $n = $n.Replace($c, '_')
  }
  $n = $n -replace '\s+', ''
  if ([string]::IsNullOrWhiteSpace($n)) { $n = 'sensor' }
  return $n
}

function Resolve-SlaveMbs([string]$Root, [int]$Addr, [string]$Name) {
  $safe = Get-SafeSensorName $Name
  $named = Join-Path $Root ("{0:D2}_{1}.mbs" -f $Addr, $safe)
  if (Test-Path $named) { return $named }
  $legacy = Join-Path $Root ("velaguard_slave{0:D2}.mbs" -f $Addr)
  if (Test-Path $legacy) { return $legacy }
  return $null
}

if (-not (Test-Path $Dir)) {
  throw "Directory not found: $Dir"
}

$Dir = (Resolve-Path $Dir).Path
$repoRoot = Split-Path -Parent $PSScriptRoot
$csvPath = Join-Path $repoRoot "config\modbus-slave\velaguard_slaves.csv"

$files = @()
if (Test-Path $csvPath) {
  $slaves = Import-Csv $csvPath
  foreach ($s in $slaves) {
    $addr = [int]$s.addr
    $path = Resolve-SlaveMbs $Dir $addr $s.name
    if (-not $path) {
      throw "Missing mbs for addr=$addr name=$($s.name) under $Dir"
    }
    $files += [pscustomobject]@{ Addr = $addr; Name = $s.name; File = $path }
  }
}
else {
  $named = Get-ChildItem -Path $Dir -Filter "*.mbs" |
    Where-Object { $_.Name -match '^\d{2}_.+\.mbs$' } |
    Sort-Object Name
  if ($named.Count -eq 0) {
    $named = 1..32 | ForEach-Object {
      Get-Item (Join-Path $Dir ("velaguard_slave{0:D2}.mbs" -f $_)) -ErrorAction SilentlyContinue
    } | Where-Object { $_ }
  }
  if ($named.Count -eq 0) {
    throw "No NN_<sensor>.mbs (or velaguard_slaveNN.mbs) in $Dir"
  }
  foreach ($f in $named) {
    $addr = [int]($f.BaseName.Substring(0, 2))
    $files += [pscustomobject]@{ Addr = $addr; Name = $f.BaseName; File = $f.FullName }
  }
}

$files = @($files | Sort-Object Addr)
Write-Output "=== Open $($files.Count) Modbus Slave docs from $Dir ==="

# OpenConnection requires COM Document lifetime; force hold mode.
if ($OpenConnection) { $ComHold = $true }
if ($KeepOpen -and -not $ComHold) { $ComHold = $true }

if (-not $ComHold) {
  # Detached: file association owns the windows; script may exit safely.
  foreach ($f in $files) {
    Start-Process -FilePath $f.File | Out-Null
    Write-Output ("addr={0,2} shell-open {1}" -f $f.Addr, (Split-Path $f.File -Leaf))
    Start-Sleep -Milliseconds 150
  }
  Write-Output ""
  Write-Output "Done. $($files.Count) windows opened via shell (survive this script exit)."
  Write-Output "Then in Modbus Slave: Connection -> Serial COM$ComPort @ $Baud 8N1 -> Connect"
  Write-Output "Need script to hold COM + OpenConnection? use -ComHold -OpenConnection"
  return
}

try {
  $app = New-Object -ComObject Mbslave.Application
}
catch {
  throw "Mbslave.Application COM failed. Install Modbus Slave and run it once."
}

$app.Connection = 0
$app.SerialPort = $ComPort
$app.BaudRate = $Baud
$app.DataBits = 8
$app.Parity = 0
$app.StopBits = 1
try { $app.Mode = 0 } catch {}

$docs = New-Object System.Collections.ArrayList
foreach ($f in $files) {
  $doc = New-Object -ComObject Mbslave.Document
  $opened = $false
  try {
    $opened = [bool]$doc.Open([string]$f.File)
  }
  catch {
    Write-Warning "COM Open failed for $($f.File): $($_.Exception.Message)"
  }
  if (-not $opened) {
    throw "Failed to COM-open $($f.File)"
  }
  try { $doc.ShowWindow() | Out-Null } catch {}
  [void]$docs.Add($doc)
  Write-Output ("addr={0,2} opened {1}" -f $f.Addr, (Split-Path $f.File -Leaf))
}

if ($OpenConnection) {
  $st = $app.OpenConnection()
  Write-Output "OpenConnection status=$st"
}

$holdSec = $KeepOpenSeconds
if ($KeepOpen -and $holdSec -le 0) { $holdSec = 0 }

# Must keep $docs / $app alive or Modbus Slave closes every document.
Write-Output ""
Write-Output "Holding $($docs.Count) COM docs alive. Close this window or press Enter to release (windows will close)."
try {
  if ($holdSec -gt 0) {
    Write-Output "Auto-release in ${holdSec}s (Ctrl+C to stop sooner)..."
    Start-Sleep -Seconds $holdSec
  }
  else {
    Read-Host "Press Enter when finished"
  }
}
finally {
  try { $app.CloseConnection() | Out-Null } catch {}
  # Explicit release so order is clear; GC would also close on exit.
  for ($i = $docs.Count - 1; $i -ge 0; $i--) {
    try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($docs[$i]) } catch {}
  }
  try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($app) } catch {}
  [GC]::Collect()
  [GC]::WaitForPendingFinalizers()
}

